import{z as s,x as A,o as e,c,q as l,j as B,D as t,d as E,s as o,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"回购与抵押品","description":"","frontmatter":{"title":"回购与抵押品","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/repo-collateral.md","filePath":"quant/repo-collateral.md","lastUpdated":1791063341000}'),u={name:"quant/repo-collateral.md"};function p(h,a,d,C,D,m){const i=A("Mermaid");return e(),c("div",null,[a[2]||(a[2]=l('<h1 id="回购与抵押品" tabindex="-1">回购与抵押品 <a class="header-anchor" href="#回购与抵押品" aria-label="Permalink to &quot;回购与抵押品&quot;">​</a></h1><div class="epigraph"><p>回购是带抵押的短期借款：你交出证券、拿回现金，到期反向操作。Haircut 决定同一张债券能换多少资金；抵押品降级时，杠杆比价格先塌。</p><footer>—— 据 Duffie, Special Repo Rates, Journal of Finance, 1996；Gorton and Metrick 对回购与 haircut 的讨论整理</footer></div><p>上一课<a href="/quant/stock-loan-fee">借券费率</a>是证券出借的价格。本课转到现金腿：回购（repo）用证券换现金。多头杠杆的机构实现往往不是 Reg T 保证金，而是回购与 Prime 融资。缺口是把<strong>抵押品与 haircut</strong>写成资金约束。不重写借券费，尽管 special repo 与借券在机制上相通。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无约束回测把国债、公司债、股票当成同样可融资的名义。回购市场上，国债 haircut 低，信用债与股票 haircut 高，危机中 haircut 上调等于抽走杠杆。Gorton–Metrick 把 2008 年描述为 haircut 驱动的挤兑：价格尚未跌完，可借现金已经下降。缺口是回测每日用<strong>当时 haircut</strong>计算可融资金，而不是用一个常数杠杆乘市值。</p><p><span class="marginnote">haircut 翻译成白话：「抵押打折」。面值 100 元的国债，haircut 2% 表示只能借到 98 元；同一金额的信用债 haircut 15%，只能借 85 元。它既不是价格也不是久期，而是清算规则与对手方信任的产物——所以它能在价格还没动的情况下，一夜从 2% 跳到 10%，凭空抽走一笔现金。</span></p><p>Duffie 指出 special repo 利率会因该券被追捧而下跌（现金出借人接受更低利息以借到该券），与上一课 special 借券费是同一稀缺的两面。</p><h3 id="haircut-不是债券久期" tabindex="-1">Haircut 不是债券久期 <a class="header-anchor" href="#haircut-不是债券久期" aria-label="Permalink to &quot;Haircut 不是债券久期&quot;">​</a></h3><p>久期描述价格对利率的敏感；haircut 是对手方与清算规则决定的抵押折扣。长久期国债仍可能 haircut 很低。把风险模型的 VaR 直接当成 haircut，会在回测里用错约束。本课把 haircut 当制度输入，可随评级、集中度、CCP 规则变，但不在此推导最优折扣。</p><p><span class="marginnote">同一证券作为融券抵押与作为回购抵押，折扣规则可以不同。不要把借券保证金率直接抄进回购账户。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>持仓按类别映射到当时 haircut，可融资额 = \\((1-h_t)\\times\\) 抵押市值。目标杠杆超过可融资额则降仓，走保证金课的拒绝开仓逻辑。抵押品价格下跌或 \\(h_t\\) 上调，触发追加抵押或减仓；追加失败走缺口强平。Haircut 时间序列必须 PIT：用危机后才升高的折扣回填危机前，会让策略在 2007 年就已经「预知」无法加杠杆。</p><p>GC 回购利率进入后课资金底；本课先把数量约束（能借多少）与价格约束（什么利率）分开。数量先绑死。</p>',13)),(e(),B(n,null,{default:t(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20COLL%5B%22%E6%8A%B5%E6%8A%BC%E8%AF%81%E5%88%B8%22%5D%20--%3E%20H%5B%22%E5%BD%93%E6%97%B6%20haircut%22%5D%0A%20%20H%20--%3E%20CASH%5B%22%E5%8F%AF%E8%9E%8D%E7%8E%B0%E9%87%91%22%5D%0A%20%20CASH%20--%3E%20LEV%5B%22%E5%8F%AF%E7%BB%B4%E6%8C%81%E6%9D%A0%E6%9D%86%22%5D%0A%20%20HUP%5B%22haircut%20%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20CALL%5B%22%E8%BF%BD%E5%8A%A0%E6%88%96%E5%87%8F%E4%BB%93%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"股票与国债不得共用 haircut 常数。\\(h_t\\) 与抵押市值同时变时先追加后减仓。事后监管校准的折扣不得回填危机前。数量约束先于 GC 利率。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"回购把资产负债表的资产变成现金，同时制造到期必须轧平的滚动风险。滚动失败（repo run）是强平的机构版本：不是股票维持线，而是隔夜合约不再续作。因子若依赖杠杆放大的价值或多空，危机里先碰到滚动与 haircut，再碰到价格。纸面回测在 2008 年仍用 2006 年的杠杆常数，是制度前视。",-1)),(e(),B(n,null,{default:t(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E9%9A%94%E5%A4%9C%E5%9B%9E%E8%B4%AD%E5%88%B0%E6%9C%9F%22%5D%20--%3E%20Q%7B%22%E5%AF%B9%E6%89%8B%E6%96%B9%E8%BF%98%E7%BB%AD%E4%BD%9C%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22haircut%20%E4%B8%8A%E8%B0%83%22%7C%20MORE%5B%22%E8%A6%81%E5%A4%9A%E4%BA%A4%E6%8A%B5%E6%8A%BC%3A%20%E5%8F%AF%E7%94%A8%E7%8E%B0%E9%87%91%E5%87%8F%E5%B0%91%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8B%92%E7%BB%9D%E7%BB%AD%E4%BD%9C%22%7C%20RUN%5B%22%E6%BB%9A%E5%8A%A8%E5%A4%B1%E8%B4%A5%3A%20%E8%A2%AB%E8%BF%AB%E5%8D%96%E5%88%B8%E8%BF%98%E9%92%B1%22%5D%0A%20%20MORE%20--%3E%20SELL%5B%22%E5%87%8F%E4%BB%93%20%2F%20%E6%8A%9B%E5%94%AE%E6%8A%B5%E6%8A%BC%E5%93%81%22%5D%0A%20%20SELL%20--%3E%20PRICE%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20PRICE%20--%3E%20H2%5B%22%E5%AF%B9%E6%89%8B%E6%96%B9%E8%BF%9B%E4%B8%80%E6%AD%A5%E4%B8%8A%E8%B0%83%20haircut%22%5D%0A%20%20H2%20--%3E%20MORE%0A%20%20RUN%20--%3E%20FIRE%5B%22%E6%8A%98%E4%BB%B7%E7%94%A9%E5%8D%96%3A%20%E6%9D%A0%E6%9D%86%E6%AF%94%E4%BB%B7%E6%A0%BC%E5%85%88%E5%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">CCP 清算会统一部分 haircut 与保证金，下一课讲。双边回购的折扣更散、更易在压力中跳变。</span></p><p>按资产类别映射当时 haircut，可融现金 = \\((1-h_t)\\) × 抵押市值。\\(h_t\\) 上调或抵押市值下跌，先追加后减仓，失败走缺口。Haircut 时间序列用当时市场惯例或 CCP 参数，2008 年用 2008 年的折扣，不要用事后监管校准值回填。GC 利率留给资金底；本课先把「能借多少」绑死。股票抵押与国债抵押不得共用一个折扣常数。</p><p><span class="marginnote">数字感受一下回购挤兑：持有 10 亿抵押品、haircut 3% 时可借 9.7 亿；危机中 haircut 升到 10%，同样抵押只能借 9 亿——缺口 7000 万必须当天补上，否则减仓。100 亿的组合对应 7 亿缺口，这就是 2008 年「价格还没跌完、钱已经借不到」的算术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 GMRA 合同条款汇编，不给 MBS 估值。下一课<a href="/quant/ccp-clearing">中央对手清算</a>把双边对手风险换成 CCP 的违约基金管理。后课默认：杠杆由当时抵押与 haircut 决定；常数杠杆倍数不是机构可交易路径。</p><p>后课 CCP 会把部分折扣规则统一；双边回购仍然更散、更顺周期。本课数量约束先于利率。危机月 haircut 上调与价格下跌同时发生，常数杠杆回测没有这条路径。抵押品降级按当时评级与当时折扣，不按事后才调低的评级回填。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回购用证券换现金；haircut 决定换多少。</li><li>危机中折扣上调会先于价格抽走杠杆。</li><li>special repo 与借券费是同一稀缺的两面。</li><li>Haircut 必须 PIT，不能用危机后规则回填。</li><li>数量约束（能借多少）先于利率（资金底）。</li><li>出处：Duffie (1996)；Gorton and Metrick 回购与 haircut 讨论。</li></ul>',8))])}const P=s(u,[["render",p]]);export{_ as __pageData,P as default};
